 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seeds = [(c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    if len(seeds) != 3:
        return out
    # Each seed is a vertical guide to the row of the matching remote marker;
    # the middle guide continues to the bottom when no matching marker exists.
    for i, (c, color) in enumerate(seeds):
        locations = [(r, x) for r in range(1, h) for x in range(w) if grid[r][x] == color]
        if locations:
            for r, x in locations:
                for rr in range(1, r + 1):
                    out[rr][c] = color
                for xx in range(min(c, x), max(c, x) + 1):
                    out[r][xx] = color
        elif i == 1:
            for rr in range(1, h):
                out[rr][c] = color
    return out
